58: const replaceInterfaceValues = (translation, parameters = {}) => {
59:   if (typeof translation !== 'string') return translation;
60:   return translation.replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g, (placeholder, name) => {
61:     const value = parameters?.[name];
62:     return typeof value === 'string' || typeof value === 'number'
63:       ? String(value)
64:       : placeholder;
65:   });
66: };
67: 
68: const formatInterfaceTextForLanguage = (source, parameters = {}, language = activeLanguage) => {
69:   if (typeof source !== 'string') return source;
70:   const localized = translationFor(source, language);
71:   const category = typeof parameters?.count === 'number'
72:     ? new Intl.PluralRules(language).select(parameters.count)
73:     : 'other';
74:   const translated = typeof localized === 'string' ? localized : localized?.[category] || localized?.other || source;
75:   return replaceInterfaceValues(translated, parameters);

